  productOrService?: string | null;
  internalOwner?: string | null;
  questionnaireSentAt?: string | null;
  respondedAt?: string | null;
  pqcRoadmapStatus?: VendorPqcRoadmapStatus | null;
  statedPqcReadyDate?: string | null;
